const fs = require('fs');

class Scanner {
    constructor() {
        const data = fs.readFileSync(0, 'utf8');
        this.tokens = data.split(/\s+/).filter(x => x.length > 0);
        this.idx = 0;
    }
    next() {
        return this.tokens[this.idx++];
    }
    nextInt() {
        return parseInt(this.next(), 10);
    }
    nextLong() {
        return BigInt(this.next());
    }
}

class Myon {
    constructor() {
        this.c = '.';
    }

    calc() {
        this.cin = new Scanner();
        const N = this.cin.nextInt();
        const MAX = 100005;
        const MAX2 = 1000000000000000010n; // (long)1e18 + 10

        this.f0 = "What are you doing at the end of the world? Are you busy? Will you save us?";
        this.s0 = "What are you doing while sending \"";
        this.s1 = "\"? Are you busy? Will you send \"";
        this.s2 = "\"?";

        this.dp = new Array(MAX);
        this.dp[0] = BigInt(this.f0.length);
        for (let i = 1; i < MAX; i++) {
            if (this.dp[i - 1] > MAX2 / 2n) {
                this.dp[i] = MAX2;
            } else {
                this.dp[i] = this.dp[i - 1] * 2n + BigInt(this.s0.length + this.s1.length + this.s2.length);
            }
        }

        let output = '';
        for (let i = 0; i < N; i++) {
            this.a = this.cin.nextInt();
            this.b = this.cin.nextLong() - 1n;

            while (this.a !== -1) this.dfs();
            output += this.c;
        }
        console.log(output);
    }

    dfs() {
        if (this.b >= this.dp[this.a]) {
            this.c = '.';
            this.a = -1;
            return;
        }
        if (this.a === 0) {
            this.c = this.f0[Number(this.b)];
            this.a = -1;
            return;
        }
        if (this.b < BigInt(this.s0.length)) {
            this.c = this.s0[Number(this.b)];
            this.a = -1;
            return;
        }
        this.b -= BigInt(this.s0.length);
        if (this.b < this.dp[this.a - 1]) {
            this.a--;
            return;
        }
        this.b -= this.dp[this.a - 1];
        if (this.b < BigInt(this.s1.length)) {
            this.c = this.s1[Number(this.b)];
            this.a = -1;
            return;
        }
        this.b -= BigInt(this.s1.length);
        if (this.b < this.dp[this.a - 1]) {
            this.a--;
            return;
        }
        this.b -= this.dp[this.a - 1];
        this.c = this.s2[Number(this.b)];
        this.a = -1;
        return;
    }
}

